<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {annotateSample} from '../api/samples';import LibrarySelector from '../components/LibrarySelector.vue';import SpectralPlot from '../components/SpectralPlot.vue';import DataTable from '../components/common/DataTable.vue';import Notice from '../components/common/Notice.vue';import {number,scientific} from '../utils/format';const s=useResearchData(),auth=useAuth(),a=useAction(),route=useRoute(),selected=ref(Number(route.query.library)||0),editing=ref(0),note=ref('');const library=computed(()=>s.libraries.find(l=>l.id===selected.value)||s.libraries[0]);watch(()=>library.value?.id,id=>{if(id)s.loadLibrary(id)},{immediate:true});async function save(){a.execute(async()=>{await annotateSample(editing.value,note.value);editing.value=0;await s.loadLibrary(library.value.id)})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">REFERENCE & MIXTURE / 02</p><h1>端元与样本<span>可辨识性与输入波段，先于配比数值。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><LibrarySelector :libraries="s.libraries" :model-value="library?.id||0" @update:model-value="selected=$event"/><div v-if="library" :class="['library-diagnostic',!library.supported?'warning':'']"><span>增广条件数 {{scientific(library.condition_number)}}</span><p>{{library.reason}}</p></div><SpectralPlot v-if="library&&s.endmembers.length" :library="library" :endmembers="s.endmembers"/><div class="section-heading"><h2>端元数值</h2><span>无量纲反射率 · 波段顺序固定</span></div><DataTable :head="['端元',...(library?.wavelengths||[]).map(w=>w+'nm')]"><tr v-for="e in s.endmembers" :key="e.id"><td>{{e.name}}</td><td v-for="(v,i) in e.spectrum" :key="i">{{number(v)}}</td></tr></DataTable><div class="section-heading"><h2>混合样本</h2><span>ls-pigment-spectra-202611.json</span></div><form v-if="editing" class="annotation" @submit.prevent="save"><label>样本备注<input aria-label="样本备注" v-model="note" minlength="8" required/></label><button class="primary" :disabled="a.busy.value">保存备注</button><button class="outline" type="button" @click="editing=0">取消</button></form><DataTable :head="['样本编号','名称','波段数','观察备注','操作']"><tr v-for="sample in s.samples" :key="sample.id"><td class="mono">{{sample.code}}</td><td>{{sample.name}}</td><td>{{sample.observed.length}}</td><td class="note-cell">{{sample.note}}</td><td><button v-if="auth.user?.role!=='viewer'" class="text-link" @click="editing=sample.id;note=sample.note">补充备注</button></td></tr></DataTable></div></template>
